import sys
from collections import defaultdict, deque

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    edges = [(int(input[i * 2 + 1]), int(input[i * 2 + 2])) for i in range(n - 1)]

    adj = defaultdict(list)
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    def dfs(node, parent):
        subtree = [node]
        for neighbor in adj[node]:
            if neighbor != parent:
                subtree.extend(dfs(neighbor, node))
        return subtree

    components = []
    visited = [False] * (n + 1)
    for node in range(1, n + 1):
        if not visited[node]:
            component = dfs(node, -1)
            components.append(component)
            for c in component:
                visited[c] = True

    m = len(components)
    print(m)
    for comp in components:
        print(len(comp), *comp)

    for i in range(1, m):
        print(i, i + 1)

if __name__ == "__main__":
    main()
